1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { AGENT_ICON_NAMES } from "@paperclipai/shared";
4	import { forbidden } from "../errors.js";
5	import { listServerAdapters } from "../adapters/index.js";
6	import { agentService } from "../services/agents.js";
7	
8	function hasCreatePermission(agent: { role: string; permissions: Record<string, unknown> | null | undefined }) {
9	  if (!agent.permissions || typeof agent.permissions !== "object") return false;
10	  return Boolean((agent.permissions as Record<string, unknown>).canCreateAgents);
11	}
12	
13	export function llmRoutes(db: Db) {
14	  const router = Router();
15	  const agentsSvc = agentService(db);
16	
17	  async function assertCanRead(req: Request) {
18	    if (req.actor.type === "board") return;
19	    if (req.actor.type !== "agent" || !req.actor.agentId) {
20	      throw forbidden("Board or permitted agent authentication required");
21	    }
22	    const actorAgent = await agentsSvc.getById(req.actor.agentId);
23	    if (!actorAgent || !hasCreatePermission(actorAgent)) {
24	      throw forbidden("Missing permission to read agent configuration reflection");
25	    }
26	  }
27	
28	  router.get("/llms/agent-configuration.txt", async (req, res) => {
29	    await assertCanRead(req);
30	    const adapters = listServerAdapters().sort((a, b) => a.type.localeCompare(b.type));
31	    const lines = [
32	      "# Paperclip Agent Configuration Index",
33	      "",
34	      "Installed adapters:",
35	      ...adapters.map((adapter) => `- ${adapter.type}: /llms/agent-configuration/${adapter.type}.txt`),
36	      "",
37	      "Related API endpoints:",
38	      "- GET /api/companies/:companyId/agent-configurations",
39	      "- GET /api/agents/:id/configuration",
40	      "- POST /api/companies/:companyId/agent-hires",
41	      "",
42	      "Agent identity references:",
43	      "- GET /llms/agent-icons.txt",
44	      "",
45	      "Notes:",
46	      "- Sensitive values are redacted in configuration read APIs.",
47	      "- New hires may be created in pending_approval state depending on company settings.",
48	      "- Use the paperclip-create-agent skill for end-to-end hiring: adapter reflection, config comparison, instruction source selection, icon choice, desiredSkills, sourceIssueId/sourceIssueIds, and approval follow-up.",
49	      "- Timer heartbeats are opt-in for new hires. Leave runtimeConfig.heartbeat.enabled false unless the role truly needs scheduled work or the user explicitly asked for it.",
50	      "",
51	    ];
52	    res.type("text/plain").send(lines.join("\n"));
53	  });
54	
55	  router.get("/llms/agent-icons.txt", async (req, res) => {
56	    await assertCanRead(req);
57	    const lines = [
58	      "# Paperclip Agent Icon Names",
59	      "",
60	      "Set the `icon` field on hire/create payloads to one of:",
61	      ...AGENT_ICON_NAMES.map((name) => `- ${name}`),
62	      "",
63	      "Example:",
64	      '{ "name": "SearchOps", "role": "researcher", "icon": "search" }',
65	      "",
66	    ];
67	    res.type("text/plain").send(lines.join("\n"));
68	  });
69	
70	  router.get("/llms/agent-configuration/:adapterType.txt", async (req, res) => {
71	    await assertCanRead(req);
72	    const adapterType = req.params.adapterType as string;
73	    const adapter = listServerAdapters().find((entry) => entry.type === adapterType);
74	    if (!adapter) {
75	      res.status(404).type("text/plain").send(`Unknown adapter type: ${adapterType}`);
76	      return;
77	    }
78	    res
79	      .type("text/plain")
80	      .send(
81	        adapter.agentConfigurationDoc ??
82	          `# ${adapterType} agent configuration\n\nNo adapter-specific documentation registered.`,
83	      );
84	  });
85	
86	  return router;
87	}
